#!/usr/bin/env node
// generated by beerpowers v{{BEERPOWERS_VERSION}} — не править: обновляет /beerpowers:update
//
// git-base — от какой ветки задача, куда её MR и какой командой смотреть её дифф.
//
//     node .claude/bin/git-base.mjs <репо> <КОД>     # задача: база, цель MR, дифф
//     node .claude/bin/git-base.mjs <репо>           # новая ветка: база по профилю
//     node .claude/bin/git-base.mjs --lost <дерево> origin/<ветка> HEAD   # что пропадёт после push
//
// --lost — перед push с силой (заливка стенда ребейзом, выравнивание, пересборка): печатает
// коммиты прежней вершины, у которых в новой истории нет пары ни по патчу, ни по теме.
// <дерево> — каталог от корня workspace, откуда пойдёт push: projects/<репо> или
// worktrees/<имя>/<репо>. Код выхода 1 — пропажи есть. Ту же проверку делает барьер guard-push.
//
// Источники, по старшинству: строка репозитория в memory/tasks/<КОД>/git-flow.md (релизная
// ветка, ветка задачи-предшественника, база custom-флоу) → профиль репозитория из
// .claude/git-settings.json → ветка по умолчанию на сервере. Правило выбора базы живёт здесь
// и в .claude/reference/git-flow.md, а не пересказом в промптах ролей: роль зовёт скрипт и берёт
// команду диффа из его ответа.
//
// Дифф считается от точки ответвления (merge-base с origin/<база>) до рабочего дерева: так
// в него попадает и незакоммиченное, но не попадает то, что влили в базу после ответвления.
// Хеш точки печатается литералом — команду можно вставить как есть, без $(…).

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { findRoot, loadWorkspace } from './lib/workspace.mjs';
import { git, lostCommits, resolve } from './lib/git.mjs';

const args = process.argv.slice(2);
const lostMode = args[0] === '--lost';
if (args.length === 0 || (lostMode ? args.length !== 4 : args.length > 2) || args[0] === '-h' || args[0] === '--help') {
  const lines = fs.readFileSync(fileURLToPath(import.meta.url), 'utf8').split('\n').slice(3);
  const end = lines.findIndex((l) => !l.startsWith('//'));
  process.stdout.write(lines.slice(0, end).map((l) => l.replace(/^\/\/ ?/, '')).join('\n') + '\n');
  process.exit(args[0] === '-h' || args[0] === '--help' ? 0 : 1);
}

const [repoName, code] = args;
let root;
try {
  root = findRoot(path.dirname(fileURLToPath(import.meta.url)));
} catch (e) {
  process.stderr.write(`${e.message}\n`);
  process.exit(2);
}

const line = (k, v) => process.stdout.write(`${k.padEnd(10)}${v}\n`);

if (lostMode) {
  const [, where, oldRef, newRef] = args;
  const abs = path.join(root, where);
  if (!fs.existsSync(abs)) {
    process.stderr.write(`git-base: нет каталога ${where}\n`);
    process.exit(2);
  }
  const l = lostCommits(abs, oldRef, newRef);
  if (l.problem) {
    process.stderr.write(`git-base: ${l.problem} в ${where}\n`);
    process.exit(2);
  }
  line('было:', `${oldRef} (${l.old.slice(0, 12)})`);
  line('станет:', `${newRef} (${l.new.slice(0, 12)})`);
  if (l.unrelated) {
    line('пропадёт:', `всё — у ${newRef} нет общей истории с ${oldRef}`);
    process.exit(1);
  }
  if (l.lost.length === 0) {
    line('пропадёт:', 'ничего');
    process.exit(0);
  }
  line('пропадёт:', `${l.lost.length} — в новой истории нет ни патча, ни темы:`);
  for (const c of l.lost) process.stdout.write(`  ${c.short} ${c.subject}\n`);
  process.exit(1);
}

const r = resolve(root, repoName, code);

line('репо:', `${r.repo ?? repoName}${r.path ? ` (${r.path})` : ''}`);
if (r.flow) line('профиль:', r.flow);
if (r.problem) {
  process.stderr.write(`git-base: ${r.problem}\n`);
  process.exit(1);
}
line('база:', `${r.base}  ← ${r.baseSource}`);
line('цель MR:', r.mr);
if (r.flow === 'dev-default') {
  line('выпуск:', r.release
    ? `${r.release} — ${r.releaseMode === 'срочно' ? 'срочно: cherry-pick -x коммита задачи' : 'плановый: merge-коммит dev целиком'}`
    : 'не определён');
}
for (const n of r.notes) line('внимание:', n);

if (code) {
  const ws = loadWorkspace(root);
  const wt = `${ws.config.worktreesDir}/${code}/${repoName}`;
  const where = fs.existsSync(path.join(root, wt)) ? wt : r.path;
  const abs = path.join(root, where);
  const branch = git(abs, ['branch', '--show-current']).out;
  const ref = git(abs, ['rev-parse', '--verify', '--quiet', `origin/${r.base}`]).ok ? `origin/${r.base}` : r.base;
  const mb = git(abs, ['merge-base', ref, 'HEAD']);
  if (branch && branch !== code) line('внимание:', `в ${where} открыта ветка ${branch}, а не ${code}`);
  if (!mb.ok) {
    line('дифф:', `не посчитать — нет общей истории с ${ref} в ${where}`);
    process.exit(1);
  }
  line('дифф:', `git -C ${where} diff ${mb.out.slice(0, 12)}   ← от ответвления от ${ref}, с незакоммиченным`);
  line('коммиты:', `git -C ${where} log --oneline ${mb.out.slice(0, 12)}..HEAD`);
}
